new="    private data class AlternativeTuning(val label: String, val notes: List<String>)\n\n    private fun tuningsFor(mode: TuningMode): List<AlternativeTuning> = when (mode) {\n        TuningMode.GUITAR -> listOf(\n            AlternativeTuning(\"Standard E · E–A–D–G–B–E\", listOf(\"E2\",\"A2\",\"D3\",\"G3\",\"B3\",\"E4\")), AlternativeTuning(\"Drop D · D–A–D–G–B–E\", listOf(\"D2\",\"A2\",\"D3\",\"G3\",\"B3\",\"E4\")), AlternativeTuning(\"Drop C · C–G–C–F–A–D\", listOf(\"C2\",\"G2\",\"C3\",\"F3\",\"A3\",\"D4\")), AlternativeTuning(\"Double Drop D\", listOf(\"D2\",\"A2\",\"D3\",\"G3\",\"B3\",\"D4\")), AlternativeTuning(\"DADGAD\", listOf(\"D2\",\"A2\",\"D3\",\"G3\",\"A3\",\"D4\")), AlternativeTuning(\"Nashville\", listOf(\"E3\",\"A3\",\"D4\",\"G4\",\"B3\",\"E4\")), AlternativeTuning(\"Open E\", listOf(\"E2\",\"B2\",\"E3\",\"G#3\",\"B3\",\"E4\")), AlternativeTuning(\"Open G\", listOf(\"D2\",\"G2\",\"D3\",\"G3\",\"B3\",\"D4\")), AlternativeTuning(\"Nick Drake · CGCFCE\", listOf(\"C2\",\"G2\",\"C3\",\"F3\",\"C4\",\"E4\")), AlternativeTuning(\"Rain Song · DGCGCD\", listOf(\"D2\",\"G2\",\"C3\",\"G3\",\"C4\",\"D4\"))\n        )\n        TuningMode.BASS -> listOf(AlternativeTuning(\"4-Saiter · E–A–D–G\", listOf(\"E1\",\"A1\",\"D2\",\"G2\")), AlternativeTuning(\"4-Saiter · Drop D\", listOf(\"D1\",\"A1\",\"D2\",\"G2\")), AlternativeTuning(\"4-Saiter · Drop C\", listOf(\"C1\",\"G1\",\"C2\",\"F2\")), AlternativeTuning(\"5-Saiter · B–E–A–D–G\", listOf(\"B0\",\"E1\",\"A1\",\"D2\",\"G2\")), AlternativeTuning(\"6-Saiter · B–E–A–D–G–C\", listOf(\"B0\",\"E1\",\"A1\",\"D2\",\"G2\",\"C3\")))\n        TuningMode.UKULELE -> listOf(AlternativeTuning(\"C-Stimmung · High G\", listOf(\"G4\",\"C4\",\"E4\",\"A4\")), AlternativeTuning(\"C-Stimmung · Low G\", listOf(\"G3\",\"C4\",\"E4\",\"A4\")), AlternativeTuning(\"D-Stimmung · A–D–F♯–B\", listOf(\"A4\",\"D4\",\"F#4\",\"B4\")), AlternativeTuning(\"Bariton · D–G–B–E\", listOf(\"D3\",\"G3\",\"B3\",\"E4\")))\n        TuningMode.VIOLIN -> listOf(AlternativeTuning(\"Standard · G–D–A–E\", listOf(\"G3\",\"D4\",\"A4\",\"E5\")), AlternativeTuning(\"Cross · A–E–A–E\", listOf(\"A3\",\"E4\",\"A4\",\"E5\")), AlternativeTuning(\"GDGD\", listOf(\"G3\",\"D4\",\"G4\",\"D5\")))\n        TuningMode.VIOLA -> listOf(AlternativeTuning(\"Standard · C–G–D–A\", listOf(\"C3\",\"G3\",\"D4\",\"A4\")), AlternativeTuning(\"D-Stimmung · D–A–E–B\", listOf(\"D3\",\"A3\",\"E4\",\"B4\")))\n        TuningMode.CELLO -> listOf(AlternativeTuning(\"Standard · C–G–D–A\", listOf(\"C2\",\"G2\",\"D3\",\"A3\")), AlternativeTuning(\"D-Stimmung · D–A–D–A\", listOf(\"D2\",\"A2\",\"D3\",\"A3\")), AlternativeTuning(\"Drop G · C–G–D–G\", listOf(\"C2\",\"G2\",\"D3\",\"G3\")))\n        TuningMode.CHROMATIC -> emptyList()\n    }\n";
s=s.slice(0,start)+new+s.slice(end);
